  values ('ME', 'short_answer', 'In what ways do fibre optics have advantages over other transmission media? (3 marks)', 'Optical fibre carries data as light, which gives several advantages over copper cable and radio: (1) very high bandwidth and data rates (gigabits to terabits per second); (2) low attenuation, so signals travel tens of kilometres without repeaters; (3) immunity to electromagnetic interference, radio noise and lightning, and no crosstalk between cables; (4) better security, because it is difficult to tap without being detected; and (5) thin, light, flexible cables that do not corrode or spark, making them safe in hazardous areas.', null, '[{"point": "Much higher bandwidth and data rates over longer distances with low signal loss (attenuation)", "marks": 1}, {"point": "Immune to electromagnetic interference and lightning; no crosstalk", "marks": 1}, {"point": "More secure (hard to tap), light weight and thin, no corrosion/ sparks; any one", "marks": 1}]'::jsonb, (select id from public.subjects where slug = 'general-subject-knowledge'),
    (select t.id from public.topics t where t.subject_id = (select id from public.subjects where slug = 'general-subject-knowledge') and t.slug = 'ict-general-subject-knowledge'), (select id from public.exam_papers where code = 'me-technical-2'), 'standard', 3,
