  values ('ME', 'short_answer', 'How does the Dynamic Host Configuration Protocol (DHCP) help in network administration? (3 marks)', 'DHCP automatically gives each device that joins the network an IP address and other settings - subnet mask, default gateway and DNS server - from a pool managed by the DHCP server, using the Discover-Offer-Request-Acknowledge (DORA) exchange. This helps administrators because: (1) they no longer configure every computer by hand, saving time when devices are added or moved; (2) it prevents errors such as duplicate or wrong IP addresses; and (3) management is central - addresses are leased and reused when devices leave, fixed addresses can be reserved for servers and printers, and a change (e.g. a new DNS server) is made once on the DHCP server.', null, '[{"point": "DHCP automatically assigns IP addresses and configuration (subnet mask, default gateway, DNS) to devices from a pool", "marks": 1}, {"point": "Saves administrators manual work and prevents errors such as duplicate IP addresses; easy to add/ move devices", "marks": 1}, {"point": "Central management: leases reuse addresses, reservations for servers/ printers, changes made once at the server (DORA process)", "marks": 1}]'::jsonb, (select id from public.subjects where slug = 'general-subject-knowledge'),
    (select t.id from public.topics t where t.subject_id = (select id from public.subjects where slug = 'general-subject-knowledge') and t.slug = 'ict-general-subject-knowledge'), (select id from public.exam_papers where code = 'me-technical-2'), 'standard', 3,
