  values ('ME', 'short_answer', 'Briefly explain the terms unicasting, multicasting and broadcasting. (3 marks)', 'Unicasting is one-to-one communication: a packet is sent from one sender to one specific receiver, as in normal web browsing or email. Multicasting is one-to-many: a single stream is sent to a group of interested receivers that have joined a multicast group (e.g. IPTV, live streaming and video conferences), saving bandwidth compared with many unicasts. Broadcasting is one-to-all: a packet is sent to every device on the local network segment, for example an ARP request or a DHCP Discover sent to 255.255.255.255.', null, '[{"point": "Unicasting: one-to-one - data sent from one sender to a single specific receiver (e.g. web browsing)", "marks": 1}, {"point": "Multicasting: one-to-many - data sent to a selected group of receivers that joined a multicast group (e.g. IPTV, video conferencing)", "marks": 1}, {"point": "Broadcasting: one-to-all - data sent to every device on the network segment (e.g. ARP request, 255.255.255.255)", "marks": 1}]'::jsonb, (select id from public.subjects where slug = 'general-subject-knowledge'),
    (select t.id from public.topics t where t.subject_id = (select id from public.subjects where slug = 'general-subject-knowledge') and t.slug = 'ict-general-subject-knowledge'), (select id from public.exam_papers where code = 'me-technical-2'), 'standard', 3,
