  values ('ME', 'short_answer', 'Provide some advantages of IPv6 over IPv4. (3 marks)', '(1) Huge address space: IPv6 uses 128-bit addresses (about 3.4 × 10^38) compared with IPv4''s 32 bits (about 4.3 billion), so every device can have a unique global address and NAT is no longer needed. (2) Efficiency: a simpler fixed-length header and no router fragmentation make routing faster; broadcast is replaced by multicast and anycast. (3) Easier configuration: stateless address auto-configuration lets devices configure themselves. (4) Security and services: IPsec support is built in, and the flow label improves quality of service, with better support for mobile devices.', null, '[{"point": "Much larger address space: 128-bit addresses (about 3.4 × 10^38) vs 32-bit, ending address shortage and the need for NAT", "marks": 1}, {"point": "Simpler, more efficient header and routing; no broadcast (multicast/ anycast instead); built-in stateless auto-configuration", "marks": 1}, {"point": "Built-in security (IPsec), better quality of service (flow label) and mobility support", "marks": 1}]'::jsonb, (select id from public.subjects where slug = 'general-subject-knowledge'),
    (select t.id from public.topics t where t.subject_id = (select id from public.subjects where slug = 'general-subject-knowledge') and t.slug = 'ict-general-subject-knowledge'), (select id from public.exam_papers where code = 'me-technical-2'), 'standard', 3,
