  values ('ME', 'short_answer', 'Name 3 relationships of a database. (3 marks)', '(1) One-to-one (1:1): one record in a table relates to only one record in another, e.g. a citizen and their CID card. (2) One-to-many (1:M): one record relates to many records in another table, e.g. one department has many employees. (3) Many-to-many (M:N): many records in one table relate to many in another, e.g. students and courses, implemented with a linking (junction) table.', null, '[{"point": "One-to-one (1:1) - e.g. one person has one passport", "marks": 1}, {"point": "One-to-many (1:M) - e.g. one department has many employees", "marks": 1}, {"point": "Many-to-many (M:N) - e.g. students and courses (implemented with a junction table)", "marks": 1}]'::jsonb, (select id from public.subjects where slug = 'general-subject-knowledge'),
