  values ('ME', 'short_answer', 'Write the 6 stages of the Software Development Life Cycle (SDLC). (3 marks)', 'The six stages of the SDLC are: (1) Planning and requirement gathering - feasibility, scope and goals; (2) Analysis - detailed requirements documented in the SRS; (3) Design - system architecture, database and interface design; (4) Implementation (coding) - writing the programs; (5) Testing - unit, integration, system and acceptance testing to find and fix defects; (6) Deployment and maintenance - installing the system for users and then correcting, updating and improving it.', null, '[{"point": "Planning/ requirement analysis; system analysis (requirements specification)", "marks": 1}, {"point": "Design; implementation (coding)", "marks": 1}, {"point": "Testing; deployment and maintenance", "marks": 1}]'::jsonb, (select id from public.subjects where slug = 'general-subject-knowledge'),
